INSERT INTO public.words (topic_id, word, phonetic, pos, meaning, example_sentence, lesson_name, lesson_order, word_order)
VALUES
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chasten', '/ˈtʃeɪsən/', 'v.', 'Trừng phạt để răn dạy, làm cho khiêm nhường hơn', 'The stinging rebuke from the senior judicial panel served to chasten the ambitious prosecutor, compelling him to observe stricter ethical boundaries.', 'Lesson 7', 7, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chastise', '/tʃæˈstaɪz/', 'v.', 'Chỉ trích gay gắt, khiển trách nặng nề', 'The congressional committee convened publicly to chastise the corporate executives for withholding crucial safety evaluations from the public.', 'Lesson 7', 7, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chauvinist', '/ˈʃoʊvɪnɪst/', 'n.', 'Kẻ theo chủ nghĩa sô-vanh, người mù quáng tôn sùng phe mình', 'In his treatise on international relations, the political theorist warned that a chauvinist often mistakes blind hostility toward foreign customs for authentic civic virtue.', 'Lesson 7', 7, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'check', '/tʃek/', 'v.', 'Kìm hãm, ngăn chặn đà phát triển', 'The constitutional framers instituted an elaborate system of divided branches to check the dangerous expansion of executive authority.', 'Lesson 7', 7, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'checkered', '/ˈtʃekərd/', 'adj.', 'Nhiều thăng trầm, đầy biến động và tì vết', 'Despite the diplomat''s checkered past, marked by ethical controversies and financial entanglements, his deep understanding of regional alliances proved indispensable.', 'Lesson 7', 7, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cherubic', '/tʃəˈruːbɪk/', 'adj.', 'Ngây thơ, phúc hậu như thiên thần', 'Beneath his cherubic countenance and gentle demeanor lay the calculating intellect of a formidable courtroom strategist.', 'Lesson 7', 7, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chicanery', '/ʃɪˈkeɪnəri/', 'n.', 'Mưu mô gian xảo, trò xảo quyệt', 'Investigative reporters uncovered an elaborate web of accounting chicanery designed to conceal the corporation''s insolvency from creditors.', 'Lesson 7', 7, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chide', '/tʃaɪd/', 'v.', 'Quở trách nhẹ nhàng, nhắc nhở bảo ban', 'The laboratory director gently chided the research fellows for skipping the secondary calibration protocols in their haste to publish.', 'Lesson 7', 7, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chimerical', '/kaɪˈmerɪkəl/', 'adj.', 'Ảo tưởng, viển vông, không tưởng', 'Prominent economists dismissed the candidate''s promise of perpetual industrial growth without inflation as a chimerical illusion.', 'Lesson 7', 7, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chisel', '/ˈtʃɪzəl/', 'v.', 'Đục đẽo; lừa đảo chiếm đoạt tiền của', 'Exploiting technical ambiguities in the probate code, the predatory broker attempted to chisel the vulnerable heirs out of their rightful inheritance.', 'Lesson 7', 7, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'choleric', '/ˈkɑːlərɪk/', 'adj.', 'Nóng nảy, hay cáu kỉnh, dễ nổi giận', 'Known for his choleric temperament, the tyrannical commander would summarily court-martial subordinates over minor infractions of camp protocol.', 'Lesson 7', 7, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'choreography', '/ˌkɔːriˈɑːɡrəfi/', 'n.', 'Nghệ thuật biên đạo múa, sự dàn dựng động tác', 'Balanchine''s avant-garde choreography dispensed with elaborate theatrical sets, focusing solely on the pure geometric precision of the dancers'' bodies.', 'Lesson 7', 7, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chortle', '/ˈtʃɔːrtəl/', 'v.', 'Cười nắc nẻ, cười khúc khích khoái chí', 'Hearing the defendant''s outlandish excuse, the seasoned magistrate began to chortle softly before composing himself to deliver the verdict.', 'Lesson 7', 7, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chronic', '/ˈkrɑːnɪk/', 'adj.', 'Kéo dài kinh niên, mãn tính, lặp đi lặp lại', 'Sociologists discovered that chronic underfunding of neighborhood municipal infrastructure directly contributed to entrenched economic stagnation.', 'Lesson 7', 7, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chronicle', '/ˈkrɑːnɪkəl/', 'n.', 'Biên niên sử, bản ghi chép sự kiện theo thời gian', 'The medieval monk''s illuminated chronicle remains an indispensable primary source for documenting daily life and climatic shocks during the Great Famine.', 'Lesson 7', 7, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'churlish', '/ˈtʃɜːrlɪʃ/', 'adj.', 'Thô lỗ, cộc cằn, khiếm nhã', 'Critics regarded it as exceptionally churlish when the prize recipient used his acceptance speech to disparage the jurists who had honored him.', 'Lesson 7', 7, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cipher', '/ˈsaɪfər/', 'n.', 'Mật mã; người vô danh không có thực quyền', 'Bletchley Park mathematicians constructed electromechanical engines to decipher the complex rotor-based cipher generated by naval Enigma machines.', 'Lesson 7', 7, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circuitous', '/sərˈkjuːɪtəs/', 'adj.', 'Vòng vo, quanh co, không trực tiếp', 'To circumvent heavily mined arterial corridors, the supply caravan took a circuitous mountain detour that added three days to the journey.', 'Lesson 7', 7, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumlocution', '/ˌsɜːrkəmləˈkjuːʃən/', 'n.', 'Cách nói vòng vo, sự dài dòng quanh co né tránh', 'Impatient with the spokesperson''s evasive circumlocution, the press corps demanded an unvarnished statement regarding the environmental impact of the pipeline.', 'Lesson 7', 7, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumscribe', '/ˈsɜːrkəmspraɪb/', 'v.', 'Giới hạn, hạn chế phạm vi', 'The landmark Supreme Court ruling sought to circumscribe the state''s power to regulate private digital communications without a warrant.', 'Lesson 7', 7, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumspect', '/ˈsɜːrkəmspekt/', 'adj.', 'Thận trọng, dè dặt, cảnh giác', 'Given the precarious geopolitical climate, the ambassador maintained a circumspect neutrality throughout the multi-state summit.', 'Lesson 7', 7, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumvent', '/ˌsɜːrkəmˈvent/', 'v.', 'Né tránh, lách luật, vượt qua khôn khéo', 'Multinational conglomerates routinely establish shell corporations in offshore tax havens to circumvent strict domestic revenue statutes.', 'Lesson 7', 7, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cistern', '/ˈsɪstərn/', 'n.', 'Bể chứa nước, bể trữ nước mưa', 'During prolonged summer droughts, the Mediterranean hilltop village relied exclusively on rainwater collected within a subterranean stone cistern.', 'Lesson 7', 7, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'citadel', '/ˈsɪtədəl/', 'n.', 'Thành trì, pháo đài kiên cố', 'Perched menacingly atop the rocky promontory, the medieval citadel commanded an unhindered defensive view of the entire harbor.', 'Lesson 7', 7, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cite', '/saɪt/', 'v.', 'Trích dẫn, viện dẫn chứng cứ', 'In her landmark paper on cognitive development, the psychologist cited extensive longitudinal studies spanning over four decades.', 'Lesson 7', 7, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clairvoyant', '/klerˈvɔɪənt/', 'n.', 'Người có khả năng thấu thị, người tiên tri', 'Although dismissing supernatural phenomena, the historian noted how the nineteenth-century spiritualist posed as a clairvoyant to sway impressionable aristocrats.', 'Lesson 7', 7, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clamber', '/ˈklæmbər/', 'v.', 'Leo trèo nhọc nhằn bằng cả tay chân', 'Weighed down by their heavy observational packs, the botanists had to clamber over slick basalt boulders to reach the rare alpine flora.', 'Lesson 7', 7, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clamor', '/ˈklæmər/', 'n.', 'Tiếng la ó ầm ĩ, sự phản đối kịch liệt từ đám đông', 'Despite the rising public clamor for immediate regulatory intervention, the legislature delayed voting on the sweeping tariff proposal.', 'Lesson 7', 7, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clandestine', '/klænˈdestɪn/', 'adj.', 'Lén lút, bí mật, bất minh', 'A clandestine meeting between factional emissaries took place in an unassuming border inn to negotiate the terms of an armistice.', 'Lesson 7', 7, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clangor', '/ˈklæŋɡər/', 'n.', 'Tiếng loảng xoảng, tiếng kim loại va đập vang rền', 'The deafening clangor of broadswords against bronze shields echoed through the mountain pass long before the dust of battle settled.', 'Lesson 7', 7, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clapper', '/ˈklæpər/', 'n.', 'Quả lắc chuông', 'Corroded by centuries of ocean mist, the heavy iron clapper broke loose from the harbor bell, silencing the town''s primary storm warning.', 'Lesson 7', 7, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clasp', '/klæsp/', 'v.', 'Nắm chặt, siết chặt; cái móc cài', 'Trembling with solemn conviction, the young diplomat clasped the parchment treaty as if it were the sole barrier preventing total war.', 'Lesson 7', 7, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'claustrophobia', '/ˌklɔːstrəˈfoʊbiə/', 'n.', 'Hội chứng sợ không gian kín hẹp', 'Submarine crew members must undergo rigorous psychological evaluations to ensure they do not suffer from latent claustrophobia during protracted deep-sea patrols.', 'Lesson 7', 7, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cleave', '/kliːv/', 'v.', 'Chẻ đôi, chia rẽ; hoặc bám chặt lấy', 'Deep ideological disagreements over federal taxation threatened to cleave the young republic into irreconcilable regional factions.', 'Lesson 7', 7, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clemency', '/ˈklemənsi/', 'n.', 'Lòng khoan dung, sự khoan hồng nhân từ', 'Despite public outrage over the seditious uprising, the monarch exercised clemency by commuting the conspirators'' death sentences to exile.', 'Lesson 7', 7, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clench', '/klentʃ/', 'v.', 'Nghiến (răng), siết chặt (nắm tay)', 'Enduring the blistering interrogation without uttering a single betraying name, the captive courier could only clench his jaw in defiant silence.', 'Lesson 7', 7, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clientele', '/ˌklaɪənˈtel/', 'n.', 'Tệp khách hàng, nhóm khách hàng quen', 'By specializing in rare Enlightenment manuscripts, the boutique antiquarian drew an affluent clientele of academic collectors and museum curators.', 'Lesson 7', 7, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'climactic', '/klaɪˈmæktɪk/', 'adj.', 'Mang tính cao trào, tạo nên đỉnh điểm', 'In the climactic sequence of the symphony, the brass fanfare ascends dramatically to resolve the harmonic tension established throughout the preceding movements.', 'Lesson 7', 7, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clime', '/klaɪm/', 'n.', 'Xứ sở, miền khí hậu', 'Disillusioned by the damp gray skies of London, the Romantic poet journeyed to an idyllic Mediterranean clime to seek restorative warmth and creative solace.', 'Lesson 7', 7, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clique', '/kliːk/', 'n.', 'Bè phái, nhóm cánh hẩu khép kín', 'An entrenched clique of senior cabinet ministers monopolized key economic decisions, effectively freezing out junior legislators and reformist advisers.', 'Lesson 7', 7, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cloister', '/ˈklɔɪstər/', 'v.', 'Sống ẩn dật, giam mình tách biệt; tu viện', 'Tired of court intrigues and bureaucratic exhaustion, the retired statesman chose to cloister himself in his countryside estate to write his memoirs.', 'Lesson 7', 7, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cloying', '/ˈklɔɪɪŋ/', 'adj.', 'Ngọt ngấy, quá ủy mị gây ngán ngẩm', 'Literary critics condemned the Victorian melodrama for its cloying sentimentality, arguing that unearned emotionalism detracted from its moral thesis.', 'Lesson 7', 7, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coagulate', '/koʊˈæɡjəleɪt/', 'v.', 'Làm đông tụ, vón cục lại', 'When snake venom containing powerful hemotoxins enters the bloodstream, it causes fibrinogen to coagulate instantly, provoking fatal thrombosis.', 'Lesson 7', 7, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coalesce', '/ˌkoʊəˈles/', 'v.', 'Hợp nhất, kết tụ thành một khối thống nhất', 'Astrophysicists hypothesize that planetary bodies originated when microscopic grains of cosmic dust coalesced under gravitational attraction over billions of years.', 'Lesson 7', 7, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coalition', '/ˌkoʊəˈlɪʃən/', 'n.', 'Khối liên minh, sự liên minh giữa các đảng phái', 'To pass the landmark environmental legislation, progressive lawmakers forged a historic coalition with moderate agrarian representatives.', 'Lesson 7', 7, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coddle', '/ˈkɑːdəl/', 'v.', 'Nuông chiều quá mức, cưng chiều thái quá', 'The rigorous military academy refused to coddle new recruits, believing that harsh conditions and strict discipline were essential to forging resilient commanders.', 'Lesson 7', 7, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'codicil', '/ˈkɑːdɪsɪl/', 'n.', 'Phụ lục di chúc, điều khoản bổ sung di chúc', 'Suspecting undue influence, the disinherited relatives contested the validity of a handwritten codicil executed only hours before the magnate''s demise.', 'Lesson 7', 7, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'codify', '/ˈkɑːdɪfaɪ/', 'v.', 'Hệ thống hóa thành luật lệ, pháp điển hóa', 'The Napoleonic Code was groundbreaking because it systematically codified civil liberties, property rights, and uniform judicial procedures across post-revolutionary France.', 'Lesson 7', 7, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coercion', '/koʊˈɜːrʒən/', 'n.', 'Sự ép buộc, cưỡng chế bằng vũ lực hoặc đe dọa', 'International human rights monitors argued that the treaty signed under implicit military coercion lacked legal legitimacy and should be nullified.', 'Lesson 7', 7, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cogent', '/ˈkoʊdʒənt/', 'adj.', 'Có sức thuyết phục, chặt chẽ, đanh thép', 'In a cogent critique of contemporary fiscal policy, the economist demonstrated how unregulated speculative lending precipitates severe banking crises.', 'Lesson 7', 7, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cogitate', '/ˈkɒdʒ.ɪ.teɪt/', 'v.', 'Suy ngẫm, suy nghĩ thấu đáo', 'Before issuing his landmark judicial opinion, the Chief Justice retreated to his rural estate to cogitate on the constitutional limits of executive emergency decrees.', 'Lesson 7', 7, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cognate', '/ˈkɒɡ.neɪt/', 'adj.', 'Cùng nguồn gốc, có họ hàng gần', 'Comparative philologists demonstrated that English ''father'' and Latin ''pater'' are cognate words descended from a single Proto-Indo-European root.', 'Lesson 7', 7, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cognitive', '/ˈkɒɡ.nə.tɪv/', 'adj.', 'Thuộc về nhận thức', 'Developmental psychologists observed that interactive bilingual immersion significantly enhances executive function and cognitive flexibility in young children.', 'Lesson 7', 7, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cognizance', '/ˈkɒɡ.nɪ.zəns/', 'n.', 'Sự nhận biết, sự thẩm tri', 'The international war crimes tribunal took judicial cognizance of satellite imagery documenting deliberate attacks on civilian infrastructure.', 'Lesson 7', 7, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cohere', '/kəʊˈhɪər/', 'v.', 'Gắn kết chặt chẽ, mạch lạc', 'Although the archival manuscript contained fragmented testimonies from disparate witnesses, its core narrative threads cohere into a devastating chronicle of the siege.', 'Lesson 7', 7, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cohesion', '/kəʊˈhiː.ʒən/', 'n.', 'Sự gắn kết, tính liên kết', 'Sociologists argue that widening income inequality erodes civic cohesion, fostering mutual suspicion among disparate economic classes.', 'Lesson 7', 7, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coiffure', '/kwɑːˈfjʊər/', 'n.', 'Kiểu tóc cầu kỳ', 'In aristocratic portraits of the French court, noblewomen displayed towering powdered coiffures adorned with miniature porcelain ships and silk flora.', 'Lesson 7', 7, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coin', '/kɔɪn/', 'v.', 'Đặt ra, sáng tạo ra (từ ngữ, thuật ngữ)', 'Confronted by totalitarian atrocities unprecedented in legal history, jurist Raphael Lemkin was forced to coin the term ''genocide'' in 1944.', 'Lesson 7', 7, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coincidence', '/kəʊˈɪn.sɪ.dəns/', 'n.', 'Sự trùng hợp ngẫu nhiên', 'Historians dismissed the assertion that the simultaneous rebellions across three continents were a mere coincidence, pointing to synchronized grain shortages driven by volcanic eruptions.', 'Lesson 7', 7, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'colander', '/ˈkɒl.ən.dər/', 'n.', 'Cái rổ có lỗ thoát nước', 'Archaeologists excavating Pompeian culinary ruins recovered a remarkably preserved bronze colander perforated with intricate geometric drainage patterns.', 'Lesson 7', 7, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collaborate', '/kəˈlæb.ə.reɪt/', 'v.', 'Hợp tác, cộng tác', 'To map the migration corridors of polar megafauna, climatologists and marine ecologists must collaborate across national and institutional boundaries.', 'Lesson 7', 7, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collage', '/ˈkɒl.ɑːʒ/', 'n.', 'Nghệ thuật cắt dán, tác phẩm ghép mảnh', 'Dadaist artists assembled visceral collages of battlefield photographs, propaganda pamphlets, and industrial scrap to protest the senseless carnage of the Great War.', 'Lesson 7', 7, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collate', '/kəˈleɪt/', 'v.', 'Đối chiếu và sắp xếp tài liệu', 'Before publishing the definitive scholarly edition, textual critics spent years collating variant readings across dozens of medieval folios.', 'Lesson 7', 7, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collateral', '/kəˈlæt.ər.əl/', 'n.', 'Tài sản thế chấp', 'Because the tenant farmers possessed no real estate to offer as collateral, commercial lenders routinely denied them the capital needed to modernize their equipment.', 'Lesson 7', 7, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'colloquial', '/kəˈləʊ.kwi.əl/', 'adj.', 'Thông tục, mang tính khẩu ngữ', 'The novelist''s dialogue achieves authentic emotional resonance by blending archaic pastoral cadences with brisk, colloquial city banter.', 'Lesson 7', 7, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compound', '/ˈkɒm.paʊnd/', 'n.', 'Hợp chất, phức hợp', 'When synthetic chemists exposed the volatile organic compound to ultraviolet radiation, its molecular bonds destabilized into inert gaseous byproducts.', 'Lesson 7', 7, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collusion', '/kəˈluː.ʒən/', 'n.', 'Sự câu kết, sự thông đồng bí mật', 'The investigative commission uncovered systemic collusion between maritime shipping cartels and regional port officials to suppress commercial competition.', 'Lesson 7', 7, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'colossal', '/kəˈlɒs.əl/', 'adj.', 'Khổng lồ, to lớn dị thường', 'Deep beneath the ocean floor, sonar surveys detected a colossal caldera whose prehistoric collapse triggered global volcanic winters.', 'Lesson 7', 7, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comatose', '/ˈkəʊ.mə.təʊs/', 'adj.', 'Hôn mê, bất tỉnh', 'Suffering from severe cerebral hypoxia after the climbing accident, the mountaineer remained comatose for days while physicians monitored his brainstem reflexes.', 'Lesson 7', 7, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'combustible', '/kəmˈbʌs.tə.bəl/', 'adj.', 'Dễ cháy, dễ phát hỏa', 'Federal fire safety mandates require industrial warehouses to store combustible solvents in reinforced, temperature-regulated containment cells.', 'Lesson 7', 7, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comely', '/ˈkʌm.li/', 'adj.', 'Duyên dáng, thanh tú, ưa nhìn', 'In Thomas Hardy’s pastoral narratives, the protagonist is described as a comely country maiden whose rustic elegance contrasts sharply with Victorian vanity.', 'Lesson 7', 7, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comeuppance', '/kʌmˈʌp.əns/', 'n.', 'Sự trừng phạt thích đáng, quả báo', 'The tyrannical mill owner finally met his comeuppance when a unified labor strike and subsequent government audits stripped him of his industrial monopoly.', 'Lesson 7', 7, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commandeer', '/ˌkɒm.ənˈdɪər/', 'v.', 'Trưng dụng, trưng thu quân sự', 'As enemy regiments closed in on the capital, besieged commanders invoked martial law to commandeer commercial locomotives for civilian evacuation.', 'Lesson 7', 7, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commemorate', '/kəˈmem.ə.reɪt/', 'v.', 'Kỷ niệm, tưởng niệm', 'The municipal assembly commissioned an obsidian memorial wall to commemorate the abolitionist reformers who organized the clandestine escape routes.', 'Lesson 7', 7, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commensurate', '/kəˈmen.sjər.ət/', 'adj.', 'Tương xứng, phù hợp', 'The university provost maintained that faculty compensation and research grants must be commensurate with institutional performance and scholarly impact.', 'Lesson 7', 7, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commiserate', '/kəˈmɪz.ə.reɪt/', 'v.', 'Bày tỏ sự cảm thông, chia sẻ nỗi buồn', 'Gathered around the hearth after the harvest failed, impoverished homesteaders could only commiserate over their mounting bank debts and blighted crops.', 'Lesson 7', 7, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commodious', '/kəˈməʊ.di.əs/', 'adj.', 'Rộng rãi, thoáng đãng', 'The architect designed a commodious lecture hall with tiered acoustic seating capable of comfortably accommodating over five hundred scholars.', 'Lesson 7', 7, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'communal', '/ˈkɒm.jə.nəl/', 'adj.', 'Thuộc về cộng đồng, dùng chung', 'Traditional Andean agrarian societies relied on communal irrigation networks maintained collectively by all village households.', 'Lesson 7', 7, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compact', '/ˈkɒm.pækt/', 'adj.', 'Nhỏ gọn, kết cấu chặt chẽ', 'To withstand gale-force Arctic winds, the explorers erected a compact dome tent engineered from interlocking carbon-fiber struts.', 'Lesson 7', 7, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comparable', '/ˈkɒm.pər.ə.bəl/', 'adj.', 'Có thể so sánh được, tương đương', 'Economists studying inflationary spirals found that post-war monetary instability in the Weimar Republic had few comparable precedents in modern history.', 'Lesson 7', 7, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compatible', '/kəmˈpæt.ə.bəl/', 'adj.', 'Tương thích, hòa hợp', 'Ecological philosophers debated whether unrestrained industrial consumerism is fundamentally compatible with global carbon neutrality.', 'Lesson 7', 7, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compelling', '/kəmˈpel.ɪŋ/', 'adj.', 'Có sức thuyết phục cao, hấp dẫn', 'The paleoclimatologist presented compelling empirical data demonstrating an unmistakable correlation between atmospheric carbon concentrations and prehistoric extinction events.', 'Lesson 7', 7, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compensatory', '/ˌkɒm.penˈseɪ.tər.i/', 'adj.', 'Có tính bù đắp, bồi thường', 'The appellate court upheld a multi-million-dollar compensatory settlement to mitigate the economic harm suffered by displaced coastal fisheries.', 'Lesson 7', 7, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compile', '/kəmˈpaɪl/', 'v.', 'Biên soạn, thu thập và tổng hợp', 'It took decades for lexicographers to compile thousands of dialectal citations into the comprehensive historical dictionary of the English language.', 'Lesson 7', 7, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complacency', '/kəmˈpleɪ.sən.si/', 'n.', 'Sự tự mãn, chủ quan', 'Prolonged fiscal surplus bred political complacency, blinding municipal policymakers to mounting infrastructure deficits until the bridges failed.', 'Lesson 7', 7, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complaisant', '/kəmˈpleɪ.zənt/', 'adj.', 'Chiều chuộng, hay nhân nhượng, dễ dãi', 'Eager to secure corporate sponsorships, the complaisant university trustees ratified the commercial contract without imposing any academic safeguards.', 'Lesson 7', 7, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complement', '/ˈkɒm.plɪ.mənt/', 'n.', 'Phần bổ sung, vật hoàn thiện', 'In physiological psychology, quantitative brain scans serve as an indispensable complement to qualitative behavioral observation.', 'Lesson 7', 7, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complementary', '/ˌkɒm.plɪˈmen.tər.i/', 'adj.', 'Bổ trợ lẫn nhau, tương hỗ', 'The botanist demonstrated that nitrogen-fixing legumes and deep-rooted grasses establish complementary rhizosphere relationships that enrich nutrient-poor soils.', 'Lesson 7', 7, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compliance', '/kəmˈplaɪ.əns/', 'n.', 'Sự tuân thủ, sự phục tùng', 'Regulatory agencies threatened severe financial sanctions if the chemical conglomerate failed to demonstrate full compliance with hazardous waste disposal statutes.', 'Lesson 7', 7, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compliant', '/kəmˈplaɪ.ənt/', 'adj.', 'Dễ phục tùng, ngoan ngoãn tuân thủ', 'Authoritarian regimes depend upon a compliant judiciary to rubber-stamp executive decrees and suppress dissent under the guise of legal procedure.', 'Lesson 7', 7, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complicity', '/kəmˈplɪs.ə.ti/', 'n.', 'Sự đồng lõa, sự tòng phạm', 'Declassified diplomatic cables exposed the foreign ministry''s tacit complicity in financing covert paramilitary operations overseas.', 'Lesson 7', 7, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'component', '/kəmˈpəʊ.nənt/', 'n.', 'Thành phần, bộ phận cấu thành', 'Rigorous empirical replication remains an essential component of modern scientific methodology, guarding against flawed experimental designs.', 'Lesson 7', 7, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'composure', '/kəmˈpəʊ.ʒər/', 'n.', 'Sự điềm tĩnh, sự tự chủ', 'Despite virulent heckling from partisan demonstrators outside the parliament, the prime minister maintained her composure throughout the policy address.', 'Lesson 7', 7, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comprehensive', '/ˌkɒm.prɪˈhen.sɪv/', 'adj.', 'Toàn diện, bao quát', 'The environmental agency released a comprehensive longitudinal study assessing the cumulative ecological impacts of hydraulic fracturing on municipal aquifers.', 'Lesson 7', 7, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compress', '/kəmˈpres/', 'v.', 'Nén lại, ép chặt', 'Subduction zones at convergent tectonic plate boundaries compress marine sediments under tremendous geothermal pressure, converting them into metamorphic schist.', 'Lesson 7', 7, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comprise', '/kəmˈpraɪz/', 'v.', 'Bao gồm, gồm có', 'The interdisciplinary research consortium will comprise geneticists, computational statisticians, and clinical oncologists from across four continents.', 'Lesson 7', 7, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compromise', '/ˈkɒm.prə.maɪz/', 'n.', 'Sự thỏa hiệp, sự dàn xếp', 'Historians consider the Great Compromise of 1787 crucial to the formation of the American republic, as it established proportional representation in the House alongside equal representation in the Senate.', 'Lesson 7', 7, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compunction', '/kəmˈpʌŋk.ʃən/', 'n.', 'Sự cắn rứt lương tâm, sự ân hận', 'Driven by ruthless corporate ambition, the unscrupulous financier raided the pension funds of thousands of factory workers without a twinge of compunction.', 'Lesson 7', 7, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compute', '/kəmˈpjuːt/', 'v.', 'Tính toán, ước tính bằng số liệu', 'Early mechanical calculating machines designed by Charles Babbage relied on brass gear trains to compute polynomial mathematical tables with unprecedented precision.', 'Lesson 7', 7, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concave', '/kɒnˈkeɪv/', 'adj.', 'Lõm, cong vào trong', 'Astronomical observatories utilize massive concave mirrors to gather distant photons from faint celestial objects and converge them onto sensitive charge-coupled detectors.', 'Lesson 7', 7, 100);